namespace Quantum.Grover {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;
    open Microsoft.Quantum.Math;
    open Microsoft.Quantum.Convert;

    // Oracle that marks the target state
    operation MarkingOracle(target : Int, qubits : Qubit[]) : Unit is Adj {
        // Convert target to binary and apply controlled-Z
        // This is a simplified version
        let n = Length(qubits);

        // Apply X to flip bits where target has 0
        for i in 0..n-1 {
            if (not ((target >>> i) &&& 1) == 1) {
                X(qubits[i]);
            }
        }

        // Apply multi-controlled Z
        Controlled Z(Most(qubits), Tail(qubits));

        // Uncompute
        for i in 0..n-1 {
            if (not ((target >>> i) &&& 1) == 1) {
                X(qubits[i]);
            }
        }
    }

    // Diffusion operator
    operation Diffusion(qubits : Qubit[]) : Unit is Adj {
        ApplyToEach(H, qubits);
        ApplyToEach(X, qubits);
        Controlled Z(Most(qubits), Tail(qubits));
        ApplyToEach(X, qubits);
        ApplyToEach(H, qubits);
    }

    @EntryPoint()
    operation RunGrover(n : Int, target : Int) : Int {
        use qubits = Qubit[n];

        // Initialize uniform superposition
        ApplyToEach(H, qubits);

        // Calculate optimal iterations
        let iterations = Round(PI() / 4.0 * Sqrt(IntAsDouble(2^ n)));

        // Grover iterations
        for _ in 1..iterations {
            MarkingOracle(target, qubits);
            Diffusion(qubits);
        }

        // Measure and return result
        let result = MeasureInteger(LittleEndian(qubits));
        return result;
    }
}
